import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        n = int(data[0].strip())
    except ValueError:
        return
    if n < 0:
        n = 0
    strings = data[1:1 + n]
    rev = [s[::-1] for s in strings]
    if len(rev) >= 2:
        rev[0], rev[-1] = rev[-1], rev[0]
    if rev:
        sys.stdout.write("\n".join(rev) + "\n")

if __name__ == "__main__":
    main()
